let studySaved={};
try{studySaved=JSON.parse(localStorage.getItem('english-study-v1')||'{}')||{}}catch{}
const study={drafts:{},words:[],read:[],written:[],mistakes:{},knownWords:[],...studySaved};
for(const k of ['words','read','written','knownWords'])if(!Array.isArray(study[k]))study[k]=[];
for(const k of ['drafts','mistakes'])if(!study[k]||typeof study[k]!=='object'||Array.isArray(study[k]))study[k]={};
function saveStudy(){try{localStorage.setItem('english-study-v1',JSON.stringify(study));return true}catch{toast('无法保存，请导出备份或复制草稿。');return false}}
function unit(id){return readingUnits.find(u=>u.id===id)}
function draft(id){return study.drafts[id]||(study.drafts[id]={})}
function wordsIn(text){return (text.match(/\b[\w]+(?:['’-][\w]+)*\b/g)||[]).length}
function recordQuizMistake(kind,id,index,choice,q){if(choice===q.answer)return;study.mistakes[`${kind}:${id}:${index}`]={kind,id,title:q.q,original:q.options[choice],correction:q.options[q.answer],note:q.why,reviewed:false,date:Date.now()};saveStudy()}
const mistakeNames={grammar:'语法',reading:'阅读',vocabulary:'词汇',writing:'写作'};
function studyHeader(title,description=''){return `<div class="study-heading"><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>`}
function renderPortal(){
 $('#breadcrumb').textContent='学习首页';
 $('#main').innerHTML=`<div class="study-shell portal"><div class="portal-intro"><span class="eyebrow">从句子开始</span><h1>读懂英文，写清楚事情。</h1><p>从软件提示到文档、邮件和观点表达。</p></div><div class="area-grid">${[['grammar','01','语法','看清句子结构，按需查规则','32 节 · 语法地图'],['reading','02','阅读','先独立理解，再检查细节',`${readingUnits.length} 篇 · 三个难度`],['writing','03','写作','消息、邮件、报告与提案',`${readingUnits.length} 个任务 · 保留修改过程`],['vocabulary','04','词汇与搭配','单词、搭配与阅读收藏',`${vocabularyBank.length} 条常用词汇 · ${study.words.length} 条收藏`]].map(([route,n,title,text,meta])=>`<a class="area-card" href="#${route}"><span class="area-number">${n}</span><h2>${title} <span>↗</span></h2><p>${text}</p><small>${meta}</small></a>`).join('')}</div><a class="review-entry" href="#revision"><strong>统一复习本</strong><span>${Object.values(study.mistakes).filter(m=>!m.reviewed).length} 条待复习 →</span></a><details class="study-plan"><summary>怎么开始？</summary><p>每天选一篇：先读 → 做理解题 → 写一小段英文 → 对照参考、修改 → 复习错误。基础顺手后再提高难度；语法遇到不懂的再查。</p><p>翻译用于检查是否读懂；英文写作练习表达自己的意思。完成文章不等于达到某个等级。</p></details><div class="backup-bar"><span>记录保存在当前浏览器</span><button id="export-study">导出备份</button><label class="import-button">导入备份<input id="import-study" type="file" accept="application/json" hidden></label><span id="import-result" role="status"></span><small>导入会合并记录；同一篇的读写草稿采用备份内容。</small></div></div>`;
 $('#export-study').onclick=()=>{const grammarDrafts={};for(const l of lessons){try{const value=localStorage.getItem('grammar-draft-'+l.id);if(value)grammarDrafts[l.id]=value}catch{}}const blob=new Blob([JSON.stringify({version:1,study,grammar:state,grammarDrafts},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='english-learning-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 $('#import-study').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(data.version!==1||!data.study||!Array.isArray(data.study.words)||!Array.isArray(data.study.read)||!Array.isArray(data.study.written)||!data.study.drafts||typeof data.study.drafts!=='object'||!data.study.mistakes||typeof data.study.mistakes!=='object')throw Error();Object.assign(study.drafts,data.study.drafts);Object.assign(study.mistakes,data.study.mistakes);for(const k of ['words','read','written','knownWords'])study[k]=[...new Set([...study[k],...(Array.isArray(data.study[k])?data.study[k]:[])])];if(data.grammar){for(const k of ['done','bookmarks'])state[k]=[...new Set([...state[k],...(Array.isArray(data.grammar[k])?data.grammar[k].filter(id=>validIds.has(id)):[])])];persist()}if(data.grammarDrafts)for(const [id,value]of Object.entries(data.grammarDrafts))if(validIds.has(id)&&typeof value==='string'&&!localStorage.getItem('grammar-draft-'+id))localStorage.setItem('grammar-draft-'+id,value);if(saveStudy()){renderPortal();$('#import-result').textContent='已合并备份'}}catch{$('#import-result').textContent='导入失败：请选择本站导出的备份。'}};
}
function renderStudyCatalog(mode){
 const writing=mode==='writing';$('#breadcrumb').textContent=writing?'写作':'阅读';
 $('#main').innerHTML=`<div class="study-shell">${studyHeader(writing?'用英文完成一件事':'阅读',writing?'先写初稿，再检查和修改。':'从软件、文档到日常事务与观点表达。')}<div class="catalog-controls"><div class="level-tabs" role="group" aria-label="难度筛选"><button data-level="all" class="selected" aria-pressed="true">全部</button>${readingLevels.map(l=>`<button data-level="${l.id}" aria-pressed="false">${l.name}</button>`).join('')}</div><label class="catalog-search">查找材料<input id="catalog-search" type="search" placeholder="标题、场景或英文表达"></label></div><p class="catalog-count" id="catalog-count" role="status"></p><div id="unit-list"></div></div>`;
 let selectedLevel='all';
 function list(){const query=$('#catalog-search').value.trim().toLowerCase();const matches=readingUnits.filter(u=>(selectedLevel==='all'||String(u.level)===selectedLevel)&&[u.title,u.genre,u.writing.task,...u.paragraphs.map(p=>p.en),...u.phrases.flat()].join(' ').toLowerCase().includes(query));$('#catalog-count').textContent=`${matches.length} ${writing?'个任务':'篇文章'}`;$('#unit-list').innerHTML=matches.length?readingLevels.filter(l=>matches.some(u=>u.level===l.id)).map(l=>`<section class="unit-level"><h2>${l.name}<small>${esc(l.detail)} · ${matches.filter(u=>u.level===l.id).length} ${writing?'个任务':'篇'}</small></h2><div class="unit-grid">${matches.filter(u=>u.level===l.id).map(u=>`<a class="unit-card" href="#${writing?'write':'read'}/${u.id}"><small>${esc(u.genre)} · ${writing?esc(u.writing.length):wordsIn(u.paragraphs.map(p=>p.en).join(' '))+' words'}</small><h3>${esc(u.title)}</h3><p>${esc(writing?u.writing.task:u.paragraphs[0].en.slice(0,100)+'…')}</p><span>${(writing?study.written:study.read).includes(u.id)?'✓ 已完成':writing&&draft(u.id).original?'有草稿':'开始 →'}</span></a>`).join('')}</div></section>`).join(''):'<div class="empty-state"><p>没有找到匹配的材料，试试其他关键词。</p></div>'}
 list();$('#catalog-search').oninput=list;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{selectedLevel=b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});list()});
}
function bindDrafts(id){document.querySelectorAll('[data-draft]').forEach(el=>{el.value=draft(id)[el.dataset.draft]||'';const count=el.parentElement.querySelector('.word-count');if(count)count.textContent=wordsIn(el.value)+' words';el.oninput=()=>{draft(id)[el.dataset.draft]=el.value;if(count)count.textContent=wordsIn(el.value)+' words';const ok=saveStudy();$('#save-status').textContent=ok?'✓ 已保存到本地':'保存失败，请复制草稿'}})}
function manualMistake(kind,id){return `<details class="manual-mistake"><summary>记下一个${kind==='reading'?'理解':'表达'}问题</summary><label>原句 / 自己的写法<textarea id="mistake-original" rows="2"></textarea></label><label>正确理解 / 修改后<textarea id="mistake-correction" rows="2"></textarea></label><label>原因或提醒<input id="mistake-note"></label><button class="button" id="add-mistake">加入复习本</button><span id="mistake-status" role="status"></span></details>`}
function bindMistake(kind,id){$('#add-mistake').onclick=()=>{const original=$('#mistake-original').value.trim(),correction=$('#mistake-correction').value.trim();if(!original||!correction){$('#mistake-status').textContent='请填写原句和修改 / 理解。';return}const key=`manual:${Date.now()}:${Math.random().toString(36).slice(2,7)}`;study.mistakes[key]={kind,id,title:unit(id).title,original,correction,note:$('#mistake-note').value.trim(),reviewed:false,date:Date.now()};if(saveStudy()){$('#mistake-status').textContent='✓ 已加入复习本';for(const s of ['#mistake-original','#mistake-correction','#mistake-note'])$(s).value=''}}}
function adjacentUnitLinks(id,route){const current=unit(id);const group=readingUnits.filter(u=>u.level===current.level),index=group.findIndex(u=>u.id===id);return `<nav class="lesson-pagination" aria-label="同难度的${route==='read'?'阅读':'写作'}">${index>0?`<a href="#${route}/${group[index-1].id}"><small>← 上一${route==='read'?'篇':'项'}</small>${esc(group[index-1].title)}</a>`:'<span></span>'}${index<group.length-1?`<a href="#${route}/${group[index+1].id}"><small>下一${route==='read'?'篇':'项'} →</small>${esc(group[index+1].title)}</a>`:`<a href="#${route==='read'?'reading':'writing'}">返回目录 →</a>`}</nav>`}
function renderReading(id){const u=unit(id);if(!u)return notFound();$('#breadcrumb').textContent=u.title;$('#main').innerHTML=`<article class="study-article"><a class="back-link" href="#reading">← 阅读</a>${studyHeader(u.title,`${readingLevels[u.level].name} · ${u.genre} · ${wordsIn(u.paragraphs.map(p=>p.en).join(' '))} words`)}<p class="material-note">本站原创练习；文中软件与行为为模拟场景。</p><div class="article-text" lang="en">${u.paragraphs.map((p,i)=>`<p><span class="paragraph-number">${i+1}</span>${esc(p.en)}</p>`).join('')}</div><section class="study-section"><h2>用自己的话说说</h2><p>写出大意，或翻译没把握的段落。</p><label class="sr-label" for="translation-draft">我的理解</label><textarea id="translation-draft" data-draft="translation" rows="5" placeholder="这段话在说什么？哪些条件不能漏掉？"></textarea><span id="save-status" role="status">自动保存在本地</span><details class="reference-answer"><summary>对照参考译文</summary>${u.paragraphs.map((p,i)=>`<p><strong>${i+1}.</strong> ${esc(p.zh)}</p>`).join('')}<small>译法可以不同，重点核对意思、条件和指代。</small></details>${manualMistake('reading',id)}</section><section id="reading-practice" class="quiz study-section"></section><section class="study-section"><h2>文中的表达</h2><div class="phrase-list">${u.phrases.map((p,i)=>`<div><div><strong lang="en">${esc(p[0])}</strong><span>${esc(p[1])}</span><p lang="en">${esc(p[2])}</p></div><button data-word="${id}:${i}" aria-pressed="${study.words.includes(id+':'+i)}">${study.words.includes(id+':'+i)?'✓ 已收藏':'+ 收藏'}</button></div>`).join('')}</div></section><div class="study-end"><button class="button" id="read-complete">${study.read.includes(id)?'✓ 已读完':'标记读完'}</button><a class="button primary" href="#write/${id}">练习相关写作 →</a></div>${adjacentUnitLinks(id,'read')}</article>`;bindDrafts(id);bindMistake('reading',id);mountPractice($('#reading-practice'),u.questions,{onAnswer:(i,c,q)=>recordQuizMistake('reading',id,i,c,q)});document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const key=b.dataset.word;study.words=study.words.includes(key)?study.words.filter(x=>x!==key):[...study.words,key];saveStudy();const has=study.words.includes(key);b.textContent=has?'✓ 已收藏':'+ 收藏';b.setAttribute('aria-pressed',String(has))});$('#read-complete').onclick=()=>{if(!study.read.includes(id))study.read.push(id);saveStudy();$('#read-complete').textContent='✓ 已读完'}}
async function copyStudyText(text){try{await navigator.clipboard.writeText(text);toast('已复制，可粘贴到你使用的 AI 中。')}catch{toast('复制失败，请手动选择提示词复制。')}}
function renderWriting(id){const u=unit(id);if(!u)return notFound();const w=u.writing;$('#breadcrumb').textContent=u.title+' · 写作';$('#main').innerHTML=`<article class="study-article"><a class="back-link" href="#writing">← 写作</a>${studyHeader(u.title,w.task)}<div class="writing-brief"><p><strong>写给谁</strong> ${esc(w.audience)}</p><p><strong>建议长度</strong> ${esc(w.length)}</p><ul>${w.requirements.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><a href="#read/${id}">阅读相关材料 →</a></div><section class="study-section"><h2>先写初稿</h2><label for="original-draft">用英文把意思写完整</label><textarea id="original-draft" data-draft="original" rows="9" lang="en" spellcheck="true" placeholder="${esc(w.starter)}"></textarea><small class="word-count"></small><span id="save-status" role="status">自动保存在本地</span></section><details class="reference-answer"><summary>检查思路与参考范文</summary><ul><li>对方能知道发生了什么、需要做什么吗？</li><li>条件、否定、时间和指代清楚吗？</li><li>动词、搭配、拼写有需要修正的吗？</li></ul><div class="model-text" lang="en">${esc(w.model)}</div><p>范文只是一种写法，保留你想表达的意思。</p></details><section class="study-section"><h2>检查，再修改</h2><details><summary>借助 AI 检查</summary><p>本站暂未连接 API。复制后发给你使用的 AI，再把有用的反馈记在下面。</p><button class="button" id="copy-prompt">复制纠错提示词 + 我的初稿</button></details><label for="feedback-draft">检查笔记 / 外部反馈</label><textarea id="feedback-draft" data-draft="feedback" rows="4" placeholder="具体是哪句？为什么改？哪些只是风格建议？"></textarea><label for="revision-draft">修改稿</label><textarea id="revision-draft" data-draft="revision" rows="9" lang="en" spellcheck="true" placeholder="根据反馈自己修改，初稿会保留。"></textarea><small class="word-count"></small>${manualMistake('writing',id)}</section><div class="study-end"><button class="button primary" id="write-complete">${study.written.includes(id)?'✓ 已完成本次写作':'完成本次写作'}</button><a href="#revision">查看复习本 →</a></div><p id="writing-status" role="status"></p>${adjacentUnitLinks(id,'write')}</article>`;bindDrafts(id);bindMistake('writing',id);$('#copy-prompt').onclick=()=>{const text=draft(id).original?.trim();if(!text)return toast('先写一份初稿。');copyStudyText(`我是英语学习者，正在练习书面阅读和表达。请用中文反馈，不要直接重写全文。\n任务：${w.task}\n要求：${w.requirements.join('；')}\n请先指出影响意思或语法的错误，解释原因；再单独列出可选的风格建议，避免把正确表达当作错误。不确定我的意思时请提问。最后给我需要自己修改的清单。\n我的初稿：\n${text}`)};$('#write-complete').onclick=()=>{if(!draft(id).original?.trim()){ $('#writing-status').textContent='请先写下初稿。';return}if(!study.written.includes(id))study.written.push(id);saveStudy();$('#write-complete').textContent='✓ 已完成本次写作';$('#writing-status').textContent='初稿、反馈和修改稿都已保留，可随时回来继续。'}}
function renderRevision(){ $('#breadcrumb').textContent='统一复习本';$('#main').innerHTML=`<div class="study-shell">${studyHeader('统一复习本','选择题答错会自动记录；理解和表达问题由你记下。')}<div class="level-tabs"><button data-kind="all" class="selected">全部</button>${Object.entries(mistakeNames).map(([k,n])=>`<button data-kind="${k}">${n}</button>`).join('')}</div><label class="review-filter"><input type="checkbox" id="show-reviewed"> 显示已复习</label><div id="mistake-list"></div></div>`;let filter='all';function list(){const items=Object.entries(study.mistakes).filter(([,m])=>(filter==='all'||m.kind===filter)&&($('#show-reviewed').checked||!m.reviewed)).sort((a,b)=>b[1].date-a[1].date);$('#mistake-list').innerHTML=items.length?items.map(([key,m])=>`<section class="review-card"><small>${esc(mistakeNames[m.kind]||'学习记录')}${m.reviewed?' · 已复习':''}</small><h2>${esc(m.title)}</h2><p class="user-answer">${esc(m.original)}</p><details><summary>查看正确答案 / 修改</summary><p>${esc(m.correction)}</p><p>${esc(m.note||'')}</p></details><div class="review-actions"><a href="#${m.kind==='grammar'?'lesson/'+encodeURIComponent(m.id):m.kind==='writing'?'write/'+encodeURIComponent(m.id):m.kind==='vocabulary'?vocabularyReviewLink(m).slice(1):'read/'+encodeURIComponent(m.id)}">回到原文 →</a><button data-reviewed="${esc(key)}">${m.reviewed?'重新加入待复习':'标记已复习'}</button></div></section>`).join(''):'<div class="empty-state"><p>这里暂无待复习记录。</p><a href="#reading">继续阅读 →</a></div>';document.querySelectorAll('[data-reviewed]').forEach(b=>b.onclick=()=>{const m=study.mistakes[b.dataset.reviewed];m.reviewed=!m.reviewed;saveStudy();list()})}list();$('#show-reviewed').onchange=list;document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{filter=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('selected',x===b));list()})}
function syncStudyNavigation(type,id){const grammar=['grammar','chapter','lesson','review','map','references'].includes(type),area=grammar?'grammar':['read','reading'].includes(type)?'reading':['write','writing'].includes(type)?'writing':type;document.body.classList.toggle('portal-page',!type);$('#chapter-nav').hidden=!grammar;$('.main-nav').hidden=!grammar;$('.side-bottom').hidden=!grammar;$('.section-label').textContent=grammar?'章节':area==='reading'?'阅读目录':area==='writing'?'写作任务':'学习';$('#study-nav').hidden=grammar;$('#study-nav').innerHTML=grammar?'':area==='reading'||area==='writing'?`<a href="#${area}" class="study-nav-home">${area==='reading'?'全部阅读':'全部任务'}</a>${readingLevels.map(l=>`<details ${l.id===(unit(id)?.level??0)?'open':''}><summary>${l.name}<span>${readingUnits.filter(u=>u.level===l.id).length}</span></summary>${readingUnits.filter(u=>u.level===l.id).map(u=>`<a href="#${area==='reading'?'read':'write'}/${u.id}" ${u.id===id?'aria-current="page" class="active"':''}>${esc(u.title)}</a>`).join('')}</details>`).join('')}`:`<a href="#vocabulary">常用词库</a><a href="#vocabulary/saved">我的收藏</a>`;}
